using VisualRelay.Guards;

namespace VisualRelay.Tests;

/// <summary>
/// Unit tests for <see cref="RetryDelayLoopsGuard"/> — detects for/while loops
/// containing both a delay call <c>Task.Delay</c>/<c>Thread.Sleep</c> AND an
/// invocation whose receiver or arguments involve <c>IGitInvoker</c>,
/// <c>RunAsync</c>, or process types. This is the <c>RunGitAsync</c> bug shape:
/// retrying failures that can never succeed.
/// </summary>
public sealed class RetryDelayLoopsGuardTests
{
    private readonly CachedSyntaxTreesFixture _trees;

    public RetryDelayLoopsGuardTests(CachedSyntaxTreesFixture trees)
    {
        _trees = trees;
    }

    /// <summary>
    /// The canonical RunGitAsync shape: a for-loop with Task.Delay backoff AND
    /// a gitInvoker.RunAsync invocation inside. Must be reported.
    /// </summary>
    [Fact]
    public void ForLoop_WithTaskDelay_AndGitInvokerRunAsync_IsReported()
    {
        const string source = """
            class C {
                async Task M(IGitInvoker gi, CancellationToken ct, TimeProvider tp) {
                    for (int attempt = 1; attempt <= 3; attempt++) {
                        var r = await gi.RunAsync("repo", new[]{"status"}, ct);
                        if (r.ExitCode == 0) return;
                        var delay = TimeSpan.FromMilliseconds(250);
                        await Task.Delay(delay, tp, ct);
                    }
                }
            }
            """;

        var violations = RetryDelayLoopsGuard.FindViolations([("Fixtures/Looper.cs", source)]);

        Assert.NotEmpty(violations);
    }

    /// <summary>
    /// A while-loop with Thread.Sleep AND Process.Start is reported.
    /// </summary>
    [Fact]
    public void WhileLoop_WithThreadSleep_AndProcessStart_IsReported()
    {
        const string source = """
            class C {
                void M() {
                    while (true) {
                        var p = Process.Start("git", "status");
                        Thread.Sleep(500);
                        if (p.ExitCode == 0) break;
                    }
                }
            }
            """;

        var violations = RetryDelayLoopsGuard.FindViolations([("Fixtures/WhileLooper.cs", source)]);

        Assert.NotEmpty(violations);
    }

    /// <summary>
    /// A for-loop with Task.Delay but NO git/process invocation is NOT reported
    /// (only a delay, no retry of anything hermeticity-sensitive).
    /// </summary>
    [Fact]
    public void ForLoop_WithDelay_WithoutGitOrProcess_IsNotReported()
    {
        const string source = """
            class C {
                async Task M(CancellationToken ct) {
                    for (int i = 0; i < 3; i++) {
                        await Task.Delay(100, ct);
                    }
                }
            }
            """;

        var violations = RetryDelayLoopsGuard.FindViolations([("Fixtures/DelayOnly.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A for-loop with a git invocation but NO delay call is NOT reported
    /// (no retry backoff — just a single attempt).
    /// </summary>
    [Fact]
    public void ForLoop_WithGitInvocation_WithoutDelay_IsNotReported()
    {
        const string source = """
            class C {
                async Task M(IGitInvoker gi, CancellationToken ct) {
                    for (int attempt = 1; attempt <= 3; attempt++) {
                        var r = await gi.RunAsync("repo", new[]{"log"}, ct);
                        if (r.ExitCode == 0) return;
                    }
                }
            }
            """;

        var violations = RetryDelayLoopsGuard.FindViolations([("Fixtures/NoDelay.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A delay-only loop (no invocation) is NOT reported.
    /// </summary>
    [Fact]
    public void SimpleRetry_WithoutDelay_IsNotReported()
    {
        const string source = """
            class C {
                void M() {
                    for (int i = 0; i < 3; i++) {
                        var result = SomeCall();
                        if (result) return;
                    }
                }
                bool SomeCall() => false;
            }
            """;

        var violations = RetryDelayLoopsGuard.FindViolations([("Fixtures/SimpleRetry.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A loop with delay and invocation where a failure classifier identifier
    /// (isSuccess) is present in the loop body — still reported (the classifier
    /// presence is noted but doesn't exempt the loop).
    /// </summary>
    [Fact]
    public void Loop_WithClassifier_IsStillReported()
    {
        const string source = """
            class C {
                async Task M(IGitInvoker gi, CancellationToken ct, TimeProvider tp) {
                    for (int attempt = 1; attempt <= 3; attempt++) {
                        var r = await gi.RunAsync("repo", new[]{"status"}, ct);
                        bool isSuccess = r.ExitCode == 0;
                        if (isSuccess) return;
                        await Task.Delay(250, tp, ct);
                    }
                }
            }
            """;

        var violations = RetryDelayLoopsGuard.FindViolations([("Fixtures/Classified.cs", source)]);

        Assert.NotEmpty(violations);
    }

    /// <summary>
    /// Task.Delay with TimeProvider (virtual-clock seam) inside a retry loop
    /// with git invocation is STILL reported — the bug is the retry of a
    /// deterministic failure, not the real-vs-virtual delay.
    /// </summary>
    [Fact]
    public void VirtualDelay_InsideRetryLoop_IsStillReported()
    {
        const string source = """
            class C {
                async Task M(IGitInvoker gi, CancellationToken ct, TimeProvider tp) {
                    for (int attempt = 1; attempt <= 3; attempt++) {
                        var r = await gi.RunAsync("repo", new[]{"status"}, ct);
                        if (r.ExitCode == 0) return;
                        await Task.Delay(TimeSpan.FromMilliseconds(250), tp, ct);
                    }
                }
            }
            """;

        var violations = RetryDelayLoopsGuard.FindViolations([("Fixtures/VirtualDelay.cs", source)]);

        Assert.NotEmpty(violations);
    }

    /// <summary>
    /// Self-exempt file is not scanned.
    /// </summary>
    [Fact]
    public void SelfExemptFile_IsNotScanned()
    {
        const string source = """
            class C {
                async Task M(IGitInvoker gi, CancellationToken ct, TimeProvider tp) {
                    for (int attempt = 1; attempt <= 3; attempt++) {
                        await gi.RunAsync("repo", new[]{"status"}, ct);
                        await Task.Delay(250, tp, ct);
                    }
                }
            }
            """;

        var violations = RetryDelayLoopsGuard.FindViolations(
            [("tools/VisualRelay.Guards/RetryDelayLoopsGuard.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// Live-tree smoke: all four matchers complete without throwing over the
    /// full tree. No count assertions — findings are informational.
    /// </summary>
    [Fact]
    public void [ENCRYPTED:fastly]L5PaJg_hs1Ma4nlf8YUdnZvbTirgVixj()
    {
        var violations = RetryDelayLoopsGuard.FindViolations(_trees.AllTrees);

        Assert.NotNull(violations);
    }
}

using VisualRelay.Guards;

namespace VisualRelay.Tests;

/// <summary>
/// Unit tests for <see cref="DiBypassGuard"/> — detects method parameters
/// defaulting to a real collaborator (<c>?? new GitInvoker()</c>,
/// <c>?? TimeProvider.System</c>) on an optional param, plus call sites
/// of that method which omit the argument while the enclosing class holds
/// <c>RelayDriverDependencies</c>. This is the <c>EarlyImplementationDetector</c>
/// bug shape: an injection seam silently bypassed.
/// </summary>
public sealed class DiBypassGuardTests
{
    private readonly CachedSyntaxTreesFixture _trees;

    public DiBypassGuardTests(CachedSyntaxTreesFixture trees)
    {
        _trees = trees;
    }

    /// <summary>
    /// The canonical EarlyImplementationDetector shape: an optional IGitInvoker
    /// parameter defaulting to new GitInvoker() via ??, and a call site in a
    /// class holding RelayDriverDependencies that omits the argument. Reported.
    /// </summary>
    [Fact]
    public void GitInvokerBypass_WithCallSiteOmission_IsReported()
    {
        const string source = """
            using VisualRelay.Core.Execution;

            class EarlyDetector {
                internal static async Task<bool> M(
                    string root, IGitInvoker? gi = null) {
                    var g = gi ?? new GitInvoker();
                    return false;
                }
            }

            class Driver {
                RelayDriverDependencies _deps;
                async Task Caller() {
                    await EarlyDetector.M("root");
                }
            }
            """;

        var violations = DiBypassGuard.FindViolations([("Fixtures/Bypass.cs", source)]);

        Assert.NotEmpty(violations);
    }

    /// <summary>
    /// A TimeProvider.System bypass on an optional parameter with a call site
    /// omission in a RelayDriverDependencies-holding class is reported.
    /// </summary>
    [Fact]
    public void TimeProviderBypass_WithCallSiteOmission_IsReported()
    {
        const string source = """
            using VisualRelay.Core.Execution;

            class Worker {
                internal static void M(TimeProvider? tp = null) {
                    var t = tp ?? TimeProvider.System;
                }
            }

            class Driver {
                RelayDriverDependencies _deps;
                void Caller() {
                    Worker.M();
                }
            }
            """;

        var violations = DiBypassGuard.FindViolations([("Fixtures/TpBypass.cs", source)]);

        Assert.NotEmpty(violations);
    }

    /// <summary>
    /// When the call site PROVIDES the bypassed argument, it is NOT reported
    /// (the seam is not being bypassed).
    /// </summary>
    [Fact]
    public void CallSiteProvidesArg_IsNotReported()
    {
        const string source = """
            using VisualRelay.Core.Execution;

            class EarlyDetector {
                internal static async Task<bool> M(
                    string root, IGitInvoker? gi = null) {
                    var g = gi ?? new GitInvoker();
                    return false;
                }
            }

            class Driver {
                RelayDriverDependencies _deps;
                async Task Caller() {
                    await EarlyDetector.M("root", _deps.GitInvoker);
                }
            }
            """;

        var violations = DiBypassGuard.FindViolations([("Fixtures/Provided.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A method with a ?? bypass default but NO call site that omits the arg
    /// is NOT reported.
    /// </summary>
    [Fact]
    public void MethodWithBypass_ButNoCallSite_IsNotReported()
    {
        const string source = """
            using VisualRelay.Core.Execution;

            class EarlyDetector {
                internal static async Task<bool> M(
                    string root, IGitInvoker? gi = null) {
                    var g = gi ?? new GitInvoker();
                    return false;
                }
            }
            """;

        var violations = DiBypassGuard.FindViolations([("Fixtures/NoCaller.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A call site omitting the arg in a class WITHOUT RelayDriverDependencies
    /// is NOT reported (the class doesn't hold the injectable seam to bypass).
    /// </summary>
    [Fact]
    public void CallSiteInClass_WithoutRelayDriverDependencies_IsNotReported()
    {
        const string source = """
            using VisualRelay.Core.Execution;

            class EarlyDetector {
                internal static async Task<bool> M(
                    string root, IGitInvoker? gi = null) {
                    var g = gi ?? new GitInvoker();
                    return false;
                }
            }

            class PlainClass {
                async Task Caller() {
                    await EarlyDetector.M("root");
                }
            }
            """;

        var violations = DiBypassGuard.FindViolations([("Fixtures/PlainCaller.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// Self-exempt file is not scanned.
    /// </summary>
    [Fact]
    public void SelfExemptFile_IsNotScanned()
    {
        const string source = """
            using VisualRelay.Core.Execution;

            class E { internal static void M(IGitInvoker? gi = null) { var g = gi ?? new GitInvoker(); } }
            class D { RelayDriverDependencies _deps; void C() { E.M(); } }
            """;

        var violations = DiBypassGuard.FindViolations(
            [("tools/VisualRelay.Guards/DiBypassGuard.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// Live-tree smoke: matcher completes without throwing over the full tree.
    /// </summary>
    [Fact]
    public void [ENCRYPTED:fastly]L5PaJg_hs1Ma4nlf8YUdnZvbTirgVixj()
    {
        var violations = DiBypassGuard.FindViolations(_trees.AllTrees);

        Assert.NotNull(violations);
    }
}

using VisualRelay.Guards;

namespace VisualRelay.Tests;

/// <summary>
/// Unit tests for <see cref="RealWaitsGuard"/> — delegates to
/// <see cref="RealSleepGuard.FindViolations"/> across all three roots (src,
/// tests, tools), PLUS inventories every <c>// vr-allow-sleep: &lt;reason&gt;</c>
/// suppression with its reason so stale exemptions get re-reviewed.
/// </summary>
public sealed class RealWaitsGuardTests
{
    private readonly CachedSyntaxTreesFixture _trees;

    public RealWaitsGuardTests(CachedSyntaxTreesFixture trees)
    {
        _trees = trees;
    }

    /// <summary>
    /// A Thread.Sleep in a non-exempt file is found by the delegated RealSleepGuard
    /// and shows up as a real-waits violation.
    /// </summary>
    [Fact]
    public void RealSleep_IsReported_AsRealWait()
    {
        const string source = "class C { void M() => Thread.Sleep(500); }";

        var violations = RealWaitsGuard.FindViolations([("src/Fixtures/Sleeper.cs", source)]);

        Assert.NotEmpty(violations);
        Assert.Contains(violations, v => v.Reason.Contains("real-waits"));
    }

    /// <summary>
    /// A Task.Delay without TimeProvider in a non-exempt file is found.
    /// </summary>
    [Fact]
    public void TaskDelayWithoutTimeProvider_IsReported()
    {
        const string source = "class C { Task M() => Task.Delay(100); }";

        var violations = RealWaitsGuard.FindViolations([("src/Fixtures/Delayer.cs", source)]);

        Assert.NotEmpty(violations);
    }

    /// <summary>
    /// A sanctioned Task.Delay with TimeProvider is NOT reported.
    /// </summary>
    [Fact]
    public void TaskDelayWithTimeProvider_IsNotReported()
    {
        const string source =
            "class C { Task M(TimeProvider tp, CancellationToken ct) => Task.Delay(TimeSpan.FromMilliseconds(50), tp, ct); }";

        var violations = RealWaitsGuard.FindViolations([("src/Fixtures/Virtual.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A suppression marker <c>// vr-allow-sleep: integration test needs real settle</c>
    /// is inventoried with its reason. The sleep line itself is suppressed but the
    /// suppression entry appears in the output.
    /// </summary>
    [Fact]
    public void AllowSleepMarker_WithReason_IsInventoried()
    {
        const string source = """
            class C {
                void M() => Thread.Sleep(500); // vr-allow-sleep: integration test needs real settle
                void N() => Console.WriteLine("hello");
            }
            """;

        var suppressions = RealWaitsGuard.FindSuppressions([("src/Fixtures/Suppressed.cs", source)]);

        Assert.NotEmpty(suppressions);
        var s = Assert.Single(suppressions);
        Assert.Contains("integration test needs real settle", s.Message);
    }

    /// <summary>
    /// A bare marker with no reason is still inventoried (not a valid suppression,
    /// but the audit shows it for completeness).
    /// </summary>
    [Fact]
    public void BareAllowSleepMarker_WithoutReason_IsStillInventoried()
    {
        const string source = """
            class C {
                void M() => Thread.Sleep(500); // vr-allow-sleep:
            }
            """;

        var suppressions = RealWaitsGuard.FindSuppressions([("src/Fixtures/Bare.cs", source)]);

        Assert.NotEmpty(suppressions);
    }

    /// <summary>
    /// Self-exempt files (RealSleepGuard's own fixtures) are excluded entirely.
    /// </summary>
    [Fact]
    public void RealSleepGuardSelfExempt_IsNotScanned()
    {
        const string source = "class C { void M() => Thread.Sleep(5000); }";

        var violations = RealWaitsGuard.FindViolations(
            [("tools/VisualRelay.Guards/RealSleepGuard.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// Live-tree smoke: matcher completes without throwing over the full tree.
    /// </summary>
    [Fact]
    public void [ENCRYPTED:fastly]L5PaJg_hs1Ma4nlf8YUdnZvbTirgVixj()
    {
        var violations = RealWaitsGuard.FindViolations(_trees.AllTrees);
        var suppressions = RealWaitsGuard.FindSuppressions(_trees.AllTrees);

        Assert.NotNull(violations);
        Assert.NotNull(suppressions);
    }
}

