    {
        const string source = "class C { void M() { Process.Start(\"git\"); } }";

        var violations = TestSideEffectsGuard.FindViolations(
            [("tests/VisualRelay.Tests/ProcessCaptureGracefulStopTests.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// Self-exempt file is not scanned.
    /// </summary>
    [Fact]
    public void SelfExemptFile_IsNotScanned()
    {
        const string source = "class C { void M() { var g = new GitInvoker(); } }";

        var violations = TestSideEffectsGuard.FindViolations(
            [("tools/VisualRelay.Guards/TestSideEffectsGuard.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A test file with no side-effect constructs yields zero violations.
    /// </summary>
    [Fact]
    public void CleanTestFile_IsNotReported()
    {
        const string source = "class C { void M() { var x = 1 + 1; } }";

        var violations = TestSideEffectsGuard.FindViolations(
            [("tests/VisualRelay.Tests/Fixtures/Clean.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// Live-tree smoke: matcher completes without throwing over the full tree.
    /// </summary>
    [Fact]
    public void [ENCRYPTED:fastly]L5PaJg_hs1Ma4nlf8YUdnZvbTirgVixj()
    {
        var violations = TestSideEffectsGuard.FindViolations(_trees.AllTrees);

        Assert.NotNull(violations);
    }
}

using VisualRelay.Guards;

namespace VisualRelay.Tests;

/// <summary>
/// Smoke test that runs all four hermeticity-audit matchers over
/// <see cref="CachedSyntaxTreesFixture.AllTrees"/> and asserts each completes
/// without throwing. No count assertions — findings are informational and
/// must not turn the suite red.
/// </summary>
public sealed class AuditGuardSmokeTests
{
    private readonly CachedSyntaxTreesFixture _trees;

    public AuditGuardSmokeTests(CachedSyntaxTreesFixture trees)
    {
        _trees = trees;
    }

    /// <summary>
    /// All four audit matchers run over the full tree and complete without
    /// throwing. Counts are not asserted — findings are diagnostic-only.
    /// </summary>
    [Fact]
    public void AllFourMatchers_OverAllTrees_CompleteWithoutThrowing()
    {
        var trees = _trees.AllTrees;

        var retryViolations = RetryDelayLoopsGuard.FindViolations(trees);
        Assert.NotNull(retryViolations);

        var diViolations = DiBypassGuard.FindViolations(trees);
        Assert.NotNull(diViolations);

        var waitViolations = RealWaitsGuard.FindViolations(trees);
        Assert.NotNull(waitViolations);

        var waitSuppressions = RealWaitsGuard.FindSuppressions(trees);
        Assert.NotNull(waitSuppressions);

        var sideEffectViolations = TestSideEffectsGuard.FindViolations(trees);
        Assert.NotNull(sideEffectViolations);
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags <c>for</c>/<c>while</c> loops containing BOTH a
/// delay call (<c>Task.Delay</c>/<c>Thread.Sleep</c>) AND an invocation whose
/// receiver or arguments involve <c>IGitInvoker</c>, <c>RunAsync</c>, or process
/// types (<c>Process.Start</c>, <c>ProcessStartInfo</c>) — the
/// <c>RunGitAsync</c> bug shape: retrying deterministic failures that can never
/// succeed (e.g. exit-128 <c>fatal: not a git repository</c>).
///
/// When a match is found the matcher reports:
/// <list type="bullet">
///   <item>the loop kind (<c>for</c> or <c>while</c>);</item>
///   <item>numeric constants found in the loop bound and delay expressions
///         (attempt counts and backoff durations);</item>
///   <item>whether any identifier in the loop suggests failure classification
///         (e.g. <c>isSuccess</c>, <c>isSuccessExit</c>, <c>*Classifier*</c>,
///         <c>shouldRetry</c>).</item>
/// </list>
///
/// An inline <c>// vr-allow-retry-delay-loop: &lt;reason&gt;</c> suppresses a
/// finding. Self-exempts its own fixture files. No I/O — callers supply the
/// (path, source) pairs.
/// </summary>
public static class RetryDelayLoopsGuard
{
    /// <summary>Describes a single retry-delay-loop violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["RetryDelayLoopsGuard.cs", "RetryDelayLoopsGuardTests.cs"];

    /// <summary>
    /// Identifiers that suggest the loop body classifies whether a failure is
    /// retriable. Presence alone doesn't exempt the loop — it only enriches
    /// the reported reason.
    /// </summary>
    private static readonly HashSet<string> ClassifierHints = new(StringComparer.OrdinalIgnoreCase)
    {
        "isSuccess", "isSuccessExit", "shouldRetry", "canRetry", "isTransient",
        "isRetryable", "isRecoverable",
    };

    private static readonly HashSet<string> DelayMethods = new(StringComparer.Ordinal)
    {
        "Delay", // Task.Delay
        "Sleep", // Thread.Sleep
    };

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>
    /// Returns every retry-delay-loop violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line. Self-exempt files yield nothing.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var violations = new List<Violation>();
        foreach (var (path, source) in files)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;
            ScanSource(path, source, violations);
        }
        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>
    /// Returns every retry-delay-loop violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Self-exempt files yield nothing.
    /// Uses pre-parsed <see cref="SyntaxTree"/> objects.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var violations = new List<Violation>();
        foreach (var (path, tree) in trees)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;
            ScanTree(path, tree, violations);
        }
        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    private static void ScanSource(string path, string source, List<Violation> sink) =>
        ScanTree(path, CSharpSyntaxTree.ParseText(source, ParseOptions), sink);

    private static void ScanTree(string path, SyntaxTree tree, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();

        foreach (var loop in root.DescendantNodes())
        {
            StatementSyntax? body = null;
            string loopKind;

            switch (loop)
            {
                case ForStatementSyntax forStmt:
                    body = forStmt.Statement;
                    loopKind = "for";
                    break;
                case WhileStatementSyntax whileStmt:
                    body = whileStmt.Statement;
                    loopKind = "while";
                    break;
                default:
                    continue;
            }

            if (body is null)
                continue;

            // Find ALL descendant invocations in the loop body.
            var bodyInvocations = body.DescendantNodes().OfType<InvocationExpressionSyntax>().ToList();

            var hasDelay = bodyInvocations.Any(IsDelayCall);
            var hasSensitiveInvocation = bodyInvocations.Any(IsSensitiveInvocation);

            if (!hasDelay || !hasSensitiveInvocation)
                continue;

            // Build the reason.
            var constants = ExtractConstants(loop, bodyInvocations);
            var hasClassifier = bodyInvocations.Any(HasClassifierIdentifier)
                                || HasClassifierInLoop(loop);

            var reason = $"retry-delay-loop: {loopKind}-loop retries a potentially deterministic failure with delay" +
                         (constants.Count > 0 ? $" (constants: {string.Join(", ", constants)})" : "") +
                         (hasClassifier ? " — failure classifier present" : " — no failure classifier found");

            var line = LineOf(text, loop.GetLocation().SourceSpan.Start);
            if (IsAllowMarked(text, line))
                continue;

            sink.Add(new Violation(path, line, SnippetOf(text, line), reason));
        }
    }

    private static bool IsDelayCall(InvocationExpressionSyntax inv)
    {
        if (inv.Expression is not MemberAccessExpressionSyntax ma)
            return false;
        var method = ma.Name.Identifier.Text;
        if (!DelayMethods.Contains(method))
            return false;
        var owner = RightmostIdentifier(ma.Expression);
        return owner is "Task" or "Thread";
    }

    private static bool IsSensitiveInvocation(InvocationExpressionSyntax inv)
    {
        if (inv.Expression is not MemberAccessExpressionSyntax ma)
            return false;

        var methodName = ma.Name.Identifier.Text;
        var receiver = ma.Expression;

        // A call whose receiver involves IGitInvoker or Process.
        if (IsGitInvokerReceiver(receiver) || IsProcessReceiver(receiver))
            return true;

        // RunAsync on anything (common on IGitInvoker, ITestRunner, etc.).
        if (methodName == "RunAsync")
            return true;

        // Process.Start
        if (methodName == "Start" && RightmostIdentifier(receiver) == "Process")
            return true;

        // Any argument that is a ProcessStartInfo creation.
        foreach (var arg in inv.ArgumentList.Arguments)
        {
            if (arg.Expression is ObjectCreationExpressionSyntax oce
                && RightmostTypeName(oce.Type) == "ProcessStartInfo")
                return true;
        }

        return false;
    }

    private static bool IsGitInvokerReceiver(ExpressionSyntax expr)
    {
        // The receiver type name contains "GitInvoker" OR the receiver is a
        // member access whose final identifier suggests git invoker.
        var name = RightmostIdentifier(expr);
        if (name.Contains("GitInvoker", StringComparison.OrdinalIgnoreCase)
            || name.Contains("gitInvoker", StringComparison.OrdinalIgnoreCase)
            || name is "gi")
            return true;

        // Walk the expression looking for a type name hint.
        if (expr is IdentifierNameSyntax id
            && id.Identifier.Text.Contains("gitInvoker", StringComparison.OrdinalIgnoreCase))
            return true;

        return false;
    }

    private static bool IsProcessReceiver(ExpressionSyntax expr)
    {
        var name = RightmostIdentifier(expr);
        return name == "Process";
    }

    private static bool HasClassifierIdentifier(InvocationExpressionSyntax inv)
    {
        // Check if the invocation is part of a statement that assigns to
        // or reads a classifier variable.
        return inv.Ancestors().OfType<StatementSyntax>().Any(stmt =>
            stmt.DescendantNodes().OfType<IdentifierNameSyntax>().Any(id =>
                ClassifierHints.Contains(id.Identifier.Text)));
    }

    private static bool HasClassifierInLoop(SyntaxNode loop)
    {
        // Look for classifier identifiers anywhere in the loop or any
        // IdentifierName containing "Classifier" substring.
        return loop.DescendantNodes().OfType<IdentifierNameSyntax>().Any(id =>
            ClassifierHints.Contains(id.Identifier.Text)
            || id.Identifier.Text.Contains("Classifier", StringComparison.Ordinal)
            || id.Identifier.Text.Contains("classifier", StringComparison.Ordinal));
    }

    private static List<string> ExtractConstants(SyntaxNode loop, List<InvocationExpressionSyntax> invocations)
    {
        var constants = new List<string>();

        // Look for numeric literals in the loop condition (attempt count).
        foreach (var lit in loop.DescendantNodes().OfType<LiteralExpressionSyntax>())
        {
            if (lit.Token.Value is int i && i is > 0 and <= 100)
            {
                // Check if this literal is in the loop condition or bound.
                var parent = lit.Parent;
                if (parent is BinaryExpressionSyntax { RawKind: (int)SyntaxKind.LessThanOrEqualExpression or (int)SyntaxKind.LessThanExpression }
                    || parent is VariableDeclaratorSyntax)
                {
                    constants.Add($"maxAttempts={i}");
                }
            }
        }

        // Look for delay constants: TimeSpan.FromMilliseconds(N),
        // TimeSpan.FromSeconds(N), or numeric literal delay args.
        foreach (var inv in invocations)
        {
            if (!IsDelayCall(inv))
                continue;

            foreach (var arg in inv.ArgumentList.Arguments)
            {
                var delayStr = ExtractDelayConstant(arg.Expression);
                if (delayStr is not null)
                    constants.Add(delayStr);
            }
        }

        return constants.Distinct().Take(6).ToList();
    }

    private static string? ExtractDelayConstant(ExpressionSyntax expr)
    {
        // TimeSpan.FromMilliseconds(250) or TimeSpan.FromSeconds(1)
        if (expr is InvocationExpressionSyntax inv
            && inv.Expression is MemberAccessExpressionSyntax ma
            && ma.Expression is MemberAccessExpressionSyntax ts
            && ts.Name.Identifier.Text is "FromMilliseconds" or "FromSeconds"
            && RightmostIdentifier(ts.Expression) == "TimeSpan")
        {
            var unit = ts.Name.Identifier.Text == "FromMilliseconds" ? "ms" : "s";
            if (inv.ArgumentList.Arguments.Count >= 1
                && inv.ArgumentList.Arguments[0].Expression is LiteralExpressionSyntax lit
                && lit.Token.Value is int val)
            {
                return $"delay={val}{unit}";
            }
        }

        // Plain numeric literal: 250 or 1000
        if (expr is LiteralExpressionSyntax literal && literal.Token.Value is int ms)
        {
            return $"delay={ms}ms";
        }

        return null;
    }

    private static bool IsAllowMarked(SourceText text, int line)
    {
        var lineText = text.Lines[line - 1].ToString();
        return lineText.Contains("// vr-allow-retry-delay-loop:", StringComparison.Ordinal)
               && lineText.Contains("vr-allow-retry-delay-loop: ")
               && !lineText.EndsWith("vr-allow-retry-delay-loop:", StringComparison.Ordinal);
    }

    private static string RightmostIdentifier(ExpressionSyntax expr) => expr switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        MemberAccessExpressionSyntax ma => ma.Name.Identifier.Text,
        _ => string.Empty,
    };

    private static string RightmostTypeName(TypeSyntax type) => type switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        QualifiedNameSyntax qn => qn.Right.Identifier.Text,
        _ => type.ToString(),
    };

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags method parameters defaulting to a real collaborator
/// (<c>?? new GitInvoker()</c>, <c>?? TimeProvider.System</c>) on an optional
/// param, plus every call site of that method which omits the argument while
/// the enclosing class holds <c>RelayDriverDependencies</c>. This is the
/// <c>EarlyImplementationDetector</c> bug shape: an injection seam silently
/// bypassed because the real collaborator is hard-coded as the default.
///
/// The matcher does a two-pass syntax-tree walk:
/// <list type="number">
///   <item><b>Pass 1</b> — find methods with optional params (= null default)
///         where the method body does <c>param ?? new GitInvoker()</c> or
///         <c>param ?? TimeProvider.System</c>. Record the containing-type name,
///         method name, parameter index, and default kind.</item>
///   <item><b>Pass 2</b> — walk all invocations matching recorded method names;
///         when the bypassed param-index argument is omitted, check if the
///         enclosing <c>ClassDeclarationSyntax</c> contains a field/property
///         typed <c>RelayDriverDependencies</c> (by type-name identifier match).
///         If so, report the call site as a bypass.</item>
/// </list>
///
/// Self-exempts its own fixture files. No I/O — callers supply the (path, source)
/// pairs.
/// </summary>
public static class DiBypassGuard
{
    /// <summary>Describes a single DI-bypass violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["DiBypassGuard.cs", "DiBypassGuardTests.cs"];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>
    /// Returns every DI-bypass violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line. Self-exempt files yield nothing.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var violations = new List<Violation>();
        foreach (var (path, source) in files)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;
            ScanSource(path, source, violations);
        }
        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>
    /// Returns every DI-bypass violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Self-exempt files yield nothing.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var violations = new List<Violation>();
        foreach (var (path, tree) in trees)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;
            ScanTree(path, tree, violations);
        }
        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>Internal record for a bypass-default method discovered in Pass 1.</summary>
    private sealed record BypassMethod(
        string ContainingTypeName,
        string MethodName,
        int ParamIndex,
        string DefaultKind); // e.g. "new GitInvoker()", "TimeProvider.System"

    private static void ScanSource(string path, string source, List<Violation> sink) =>
        ScanTree(path, CSharpSyntaxTree.ParseText(source, ParseOptions), sink);

    private static void ScanTree(string path, SyntaxTree tree, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();

        // --- Pass 1: find methods with bypass-default optional params ---
        var bypassMethods = new List<BypassMethod>();

        foreach (var method in root.DescendantNodes().OfType<MethodDeclarationSyntax>())
        {
            var containingType = method.Parent is ClassDeclarationSyntax cls
                ? cls.Identifier.Text
                : string.Empty;

            var parameters = method.ParameterList.Parameters;
            for (int i = 0; i < parameters.Count; i++)
            {
                var param = parameters[i];
                if (param.Default is null || param.Default.Value is not LiteralExpressionSyntax lit)
                    continue;
                if (lit.Token.Value is not null) // null literal
                    continue;

                // Look in the method body for: paramId ?? <real-collaborator>
                var paramId = param.Identifier.Text;
                var body = (SyntaxNode?)method.Body ?? method.ExpressionBody;
                if (body is null)
                    continue;

                var defaultKind = FindBypassDefault(body, paramId);
                if (defaultKind is null)
                    continue;

                bypassMethods.Add(new BypassMethod(
                    containingType, method.Identifier.Text, i, defaultKind));
            }
        }

        if (bypassMethods.Count == 0)
            return;

        // --- Pass 2: find call sites that omit the bypassed arg, in Dependencies-holding classes ---
        foreach (var call in root.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            if (call.Expression is not MemberAccessExpressionSyntax ma)
            {
                // Simple name call: MethodName(args) — match on method name only.
                if (call.Expression is not IdentifierNameSyntax simple)
                    continue;
                var simpleName = simple.Identifier.Text;
                var matching = bypassMethods.Where(bm => bm.MethodName == simpleName).ToList();
                if (matching.Count == 0)
                    continue;

                var argCount = call.ArgumentList.Arguments.Count;
                foreach (var bm in matching)
                {
                    if (argCount <= bm.ParamIndex)
                    {
                        if (EnclosingClassHoldsDependencies(call))
                        {
                            var line = LineOf(text, call.SpanStart);
                            sink.Add(new Violation(path, line, SnippetOf(text, line),
                                $"di-bypass: call to {bm.MethodName} omits param #{bm.ParamIndex + 1} " +
                                $"which defaults to {bm.DefaultKind} — enclosing class holds RelayDriverDependencies"));
                        }
                    }
                }
            }
            else
            {
                // Qualified call: receiver.MethodName(args)
                var calleeName = ma.Name.Identifier.Text;
                var matchingForQualified = bypassMethods
                    .Where(bm => bm.MethodName == calleeName)
                    .ToList();
                if (matchingForQualified.Count == 0)
                    continue;

                var argCount = call.ArgumentList.Arguments.Count;
                foreach (var bm in matchingForQualified)
                {
                    // For qualified calls, also check the receiver matches the containing type.
                    var receiverType = RightmostIdentifier(ma.Expression);
                    if (!string.IsNullOrEmpty(bm.ContainingTypeName)
                        && !string.Equals(receiverType, bm.ContainingTypeName, StringComparison.Ordinal))
                        continue;

                    if (argCount <= bm.ParamIndex)
                    {
                        if (EnclosingClassHoldsDependencies(call))
                        {
                            var line = LineOf(text, call.SpanStart);
                            sink.Add(new Violation(path, line, SnippetOf(text, line),
                                $"di-bypass: call to {bm.ContainingTypeName}.{bm.MethodName} omits param #{bm.ParamIndex + 1} " +
                                $"which defaults to {bm.DefaultKind} — enclosing class holds RelayDriverDependencies"));
                        }
                    }
                }
            }
        }
    }

    /// <summary>
    /// Searches the method body for a coalesce expression of the form
    /// <c>paramId ?? new GitInvoker()</c> or <c>paramId ?? TimeProvider.System</c>.
    /// Returns a human-readable description of the default, or null if not found.
    /// </summary>
    private static string? FindBypassDefault(SyntaxNode body, string paramId)
    {
        foreach (var coalesce in body.DescendantNodes().OfType<BinaryExpressionSyntax>())
        {
            if (!coalesce.IsKind(SyntaxKind.CoalesceExpression))
                continue;

            if (coalesce.Left is IdentifierNameSyntax id && id.Identifier.Text == paramId)
            {
                var right = coalesce.Right;
                return DescribeDefault(right);
            }
        }

        return null;
    }

    private static string? DescribeDefault(ExpressionSyntax expr)
    {
        if (expr is ObjectCreationExpressionSyntax oce
            && RightmostTypeName(oce.Type) is { } typeName
            && (typeName.StartsWith("Git", StringComparison.Ordinal) || typeName == "GitInvoker"))
        {
            return $"new {typeName}()";
        }

        if (expr is MemberAccessExpressionSyntax ma
            && ma.Name.Identifier.Text == "System"
            && RightmostIdentifier(ma.Expression) == "TimeProvider")
        {
            return "TimeProvider.System";
        }

        return null;
    }

    /// <summary>
    /// True when the nearest enclosing ClassDeclarationSyntax of <paramref name="node"/>
    /// contains a field or property whose type name is <c>RelayDriverDependencies</c>.
    /// </summary>
    private static bool EnclosingClassHoldsDependencies(SyntaxNode node)
    {
        var cls = node.FirstAncestorOrSelf<ClassDeclarationSyntax>();
        if (cls is null)
            return false;

        // Check fields.
        foreach (var field in cls.Members.OfType<FieldDeclarationSyntax>())
        {
            var typeName = RightmostTypeName(field.Declaration.Type);
            if (typeName == "RelayDriverDependencies")
                return true;
        }

        // Check properties.
        foreach (var prop in cls.Members.OfType<PropertyDeclarationSyntax>())
        {
            var typeName = RightmostTypeName(prop.Type);
            if (typeName == "RelayDriverDependencies")
                return true;
        }

        return false;
    }

    private static string RightmostIdentifier(ExpressionSyntax expr) => expr switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        MemberAccessExpressionSyntax ma => ma.Name.Identifier.Text,
        _ => string.Empty,
    };

    private static string RightmostTypeName(TypeSyntax type) => type switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        QualifiedNameSyntax qn => qn.Right.Identifier.Text,
        _ => type.ToString(),
    };

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using System.Text.RegularExpressions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher for the <c>real-waits</c> audit rule. It serves two purposes:
/// <list type="number">
///   <item><b>Violation inventory</b> — delegates to
///         <see cref="RealSleepGuard.FindViolations(IEnumerable{ValueTuple{string, string}})"/>
///         and returns every real-sleep violation across all three roots (src/,
///         tests/, tools/), tagging each finding with <c>real-waits:</c>. This is
///         the enforcement counterpart of the audit tool.</item>
///   <item><b>Suppression inventory</b> — scans every source for
///         <c>// vr-allow-sleep: &lt;reason&gt;</c> markers and records each one
///         (bare or with reason) so stale exemptions get re-reviewed instead of
///         living forever. This is a separate method
///         (<see cref="FindSuppressions"/>) — it never interferes with violation
///         detection.</item>
/// </list>
///
/// Self-exempts its own fixture files AND RealSleepGuard's self-exempt files
/// (since those contain test sleep fixtures).
/// </summary>
public static class RealWaitsGuard
{
    /// <summary>Describes a single real-waits violation or suppression entry.</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    /// <summary>A suppression marker — matches both bare <c>vr-allow-sleep:</c> and reasoned forms.</summary>
    private static readonly Regex AllowMarkerRegex =
        new(@"//\s*vr-allow-sleep:\s*(.*)", RegexOptions.Compiled);

    /// <summary>Filenames whose own bodies legitimately contain sleep fixtures.
    /// Includes both our own fixture files and RealSleepGuard's.</summary>
    private static readonly string[] SelfExemptFileNames =
    [
        "RealWaitsGuard.cs", "RealWaitsGuardTests.cs",
        "RealSleepGuard.cs", "RealSleepGuardTests.cs",
    ];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>
    /// Returns every real-waits violation across <paramref name="files"/> by
    /// delegating to <see cref="RealSleepGuard.FindViolations(IEnumerable{ValueTuple{string, string}})"/>.
    /// Self-exempt files yield nothing. Findings are tagged <c>real-waits: </c>.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        // RealSleepGuard already handles its own self-exempt + integration-exempt files.
        // We additionally self-exempt our own fixture files.
        var filtered = files.Where(f => !SelfExemptFileNames.Contains(Path.GetFileName(f.Path))).ToList();

        var sleepViolations = RealSleepGuard.FindViolations(filtered);

        // Re-wrap with real-waits tag for the audit tool to distinguish from raw sleep matcher.
        return sleepViolations
            .Select(sv => new Violation(sv.Path, sv.Line, sv.Snippet,
                "real-waits: " + sv.Reason))
            .ToList();
    }

    /// <summary>
    /// Returns every real-waits violation across <paramref name="trees"/> by
    /// delegating to the SyntaxTree overload of <see cref="RealSleepGuard"/>.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var filtered = trees.Where(t => !SelfExemptFileNames.Contains(Path.GetFileName(t.Path))).ToList();

        var sleepViolations = RealSleepGuard.FindViolations(filtered);

        return sleepViolations
            .Select(sv => new Violation(sv.Path, sv.Line, sv.Snippet,
                "real-waits: " + sv.Reason))
            .ToList();
    }

    /// <summary>
    /// Returns an inventory of every <c>// vr-allow-sleep:</c> suppression marker
    /// found in <paramref name="files"/>, with the reason (if any) extracted.
    /// Self-exempt files are skipped. Bare markers (no reason) are included with
    /// a note. Findings are ordered by path then line.
    /// </summary>
    public static IReadOnlyList<Violation> FindSuppressions(IEnumerable<(string Path, string Source)> files)
    {
        var entries = new List<Violation>();

        foreach (var (path, source) in files)
        {
            var fileName = Path.GetFileName(path);
            if (SelfExemptFileNames.Contains(fileName))
                continue;

            var lines = source.Split('\n');
            for (int i = 0; i < lines.Length; i++)
            {
                var match = AllowMarkerRegex.Match(lines[i]);
                if (!match.Success)
                    continue;

                var reason = match.Groups[1].Value.Trim();
                var message = string.IsNullOrEmpty(reason)
                    ? $"real-waits suppression: // vr-allow-sleep: (bare — no reason given, not a valid suppression)"
                    : $"real-waits suppression: // vr-allow-sleep: {reason}";

                entries.Add(new Violation(path, i + 1, lines[i].Trim(), message));
            }
        }

        entries.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return entries;
    }

    /// <summary>
    /// Returns an inventory of every <c>// vr-allow-sleep:</c> suppression marker
    /// found in <paramref name="trees"/> (pre-parsed). Extraction is done from
    /// the source text.
    /// </summary>
    public static IReadOnlyList<Violation> FindSuppressions(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var entries = new List<Violation>();

        foreach (var (path, tree) in trees)
        {
            var fileName = Path.GetFileName(path);
            if (SelfExemptFileNames.Contains(fileName))
                continue;

            var text = tree.GetText();
            foreach (var lineSpan in text.Lines)
            {
                var lineText = lineSpan.ToString();
                var match = AllowMarkerRegex.Match(lineText);
                if (!match.Success)
                    continue;

                var reason = match.Groups[1].Value.Trim();
                var message = string.IsNullOrEmpty(reason)
                    ? $"real-waits suppression: // vr-allow-sleep: (bare — no reason given, not a valid suppression)"
                    : $"real-waits suppression: // vr-allow-sleep: {reason}";

                entries.Add(new Violation(path, lineSpan.LineNumber + 1, lineText.Trim(), message));
            }
        }

        entries.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return entries;
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags test sources (files whose path contains <c>/tests/</c>)
/// referencing real-side-effect constructs:
/// <list type="bullet">
///   <item><c>new GitInvoker(</c> — prefer <c>NullGitInvoker</c> or
///         <c>GitSim</c>;</item>
///   <item><c>Process.Start</c> and <c>new ProcessStartInfo(</c> — prefer
///         <c>ScriptedTestRunner</c>;</item>
///   <item><c>Environment.SetEnvironmentVariable</c> — prefer
///         <c>DictionaryEnvironmentAccessor</c>.</item>
/// </list>
///
/// Honors <see cref="RealSleepGuard"/>'s slow-integration exemption list
/// (<c>ProcessCaptureGracefulStopTests.cs</c>, <c>SandboxedTestRunnerReapTests.cs</c>,
/// <c>ActivityWatchdogSocketWedgeTests.cs</c>, <c>FdLeakTests.cs</c>,
/// <c>WindowsExecutionTests.cs</c>) — those files are exempt because their real
/// side effects run only behind <c>SlowIntegration.SkipIfNotOptedIn()</c>.
/// Self-exempts its own fixture files. No I/O — callers supply the (path, source)
/// pairs.
/// </summary>
public static class TestSideEffectsGuard
{
    /// <summary>Describes a single test-side-effect violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["TestSideEffectsGuard.cs", "TestSideEffectsGuardTests.cs"];

    /// <summary>
    /// Opt-in slow-integration files honored from RealSleepGuard's exemption list.
    /// </summary>
    private static readonly string[] RealIntegrationExemptFileNames =
    [
        "ProcessCaptureGracefulStopTests.cs",
        "SandboxedTestRunnerReapTests.cs",
        "ActivityWatchdogSocketWedgeTests.cs",
        "FdLeakTests.cs",
        "WindowsExecutionTests.cs",
    ];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>
    /// Returns every test-side-effect violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line. Only test sources are scanned; non-test
    /// paths yield nothing. Self-exempt and integration-exempt files yield nothing.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var violations = new List<Violation>();
        foreach (var (path, source) in files)
        {
            if (!IsTestPath(path))
                continue;
            var fileName = Path.GetFileName(path);
            if (SelfExemptFileNames.Contains(fileName)
                || RealIntegrationExemptFileNames.Contains(fileName))
                continue;
            ScanSource(path, source, violations);
        }
        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>
    /// Returns every test-side-effect violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Uses pre-parsed <see cref="SyntaxTree"/>
    /// objects.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var violations = new List<Violation>();
        foreach (var (path, tree) in trees)
        {
            if (!IsTestPath(path))
                continue;
            var fileName = Path.GetFileName(path);
            if (SelfExemptFileNames.Contains(fileName)
                || RealIntegrationExemptFileNames.Contains(fileName))
                continue;
            ScanTree(path, tree, violations);
        }
        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    private static bool IsTestPath(string path) =>
        path.Replace('\\', '/').Contains("/tests/", StringComparison.Ordinal);

    private static void ScanSource(string path, string source, List<Violation> sink) =>
        ScanTree(path, CSharpSyntaxTree.ParseText(source, ParseOptions), sink);

    private static void ScanTree(string path, SyntaxTree tree, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();
        var seen = new HashSet<int>();

        foreach (var node in root.DescendantNodes())
        {
            int? line = null;
            string? reason = null;

            switch (node)
            {
                // new GitInvoker()
                case ObjectCreationExpressionSyntax oce
                    when RightmostTypeName(oce.Type) is "GitInvoker":
                    line = LineOf(text, oce.NewKeyword.SpanStart);
                    reason = "test-side-effect: new GitInvoker() — prefer NullGitInvoker or GitSim for hermetic tests";
                    break;

                // new ProcessStartInfo(...)
                case ObjectCreationExpressionSyntax oce2
                    when RightmostTypeName(oce2.Type) == "ProcessStartInfo":
                    line = LineOf(text, oce2.NewKeyword.SpanStart);
                    reason = "test-side-effect: new ProcessStartInfo(...) — prefer ScriptedTestRunner for hermetic tests";
                    break;

                // Process.Start(...)
                case InvocationExpressionSyntax inv
                    when inv.Expression is MemberAccessExpressionSyntax { Name.Identifier.Text: "Start" } ma
                         && RightmostIdentifier(ma.Expression) == "Process":
                    line = LineOf(text, ma.Name.SpanStart);
                    reason = "test-side-effect: Process.Start(...) — prefer ScriptedTestRunner for hermetic tests";
                    break;

                // Environment.SetEnvironmentVariable(...)
                case InvocationExpressionSyntax inv2
                    when inv2.Expression is MemberAccessExpressionSyntax
                    {
                        Name.Identifier.Text: "SetEnvironmentVariable"
                    } ma2
                    && RightmostIdentifier(ma2.Expression) == "Environment":
                    line = LineOf(text, ma2.Name.SpanStart);
                    reason = "test-side-effect: Environment.SetEnvironmentVariable(...) — prefer DictionaryEnvironmentAccessor for hermetic tests";
                    break;
            }

            if (line.HasValue && reason is not null && seen.Add(line.Value))
            {
                sink.Add(new Violation(path, line.Value, SnippetOf(text, line.Value), reason));
            }
        }
    }

    private static string RightmostIdentifier(ExpressionSyntax expr) => expr switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        MemberAccessExpressionSyntax ma => ma.Name.Identifier.Text,
        _ => string.Empty,
    };

    private static string RightmostTypeName(TypeSyntax type) => type switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        QualifiedNameSyntax qn => qn.Right.Identifier.Text,
        _ => type.ToString(),
    };

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using VisualRelay.Guards;

namespace VisualRelay.Audit;

/// <summary>
/// Thin renderer for audit findings. Produces:
/// <list type="bullet">
///   <item>Per-finding blocks: <c>path:line: &lt;rule-id&gt;: &lt;message&gt;</c></item>
///   <item>Indented explanation and suggested-direction lines</item>
///   <item>Per-rule summary table with counts and total runtime</item>
/// </list>
/// All output goes to <see cref="Console.Out"/>. No external formatting lib.
/// </summary>
internal static class AuditRenderer
{
    /// <summary>Renders a complete audit report for all rules.</summary>
    public static void Render(
        IReadOnlyDictionary<string, IReadOnlyList<ViolationRecord>> findingsByRule,
        TimeSpan elapsed)
    {
        var totalFindings = 0;
        var rulesWithFindings = new List<(string RuleId, int Count)>();

        foreach (var (ruleId, findings) in findingsByRule.OrderBy(kv => kv.Key))
        {
            var count = findings.Count;
            totalFindings += count;
            rulesWithFindings.Add((ruleId, count));

            if (count > 0)
            {
                Console.WriteLine($"=== {ruleId} ({count} finding{(count == 1 ? "" : "s")}) ===");
                Console.WriteLine();

                foreach (var f in findings)
                {
                    // Primary line: path:line: rule-id: message
                    Console.WriteLine($"{f.Path}:{f.Line}: {ruleId}: {f.Message}");

                    // Explanation (from the reason/message)
                    Console.WriteLine($"  explanation: {f.Explanation}");

                    // Suggested direction
                    Console.WriteLine($"  direction: {f.Direction}");

                    Console.WriteLine();
                }
            }
            else
            {
                Console.WriteLine($"=== {ruleId} (0 findings) ===");
                Console.WriteLine();
            }
        }

        // Summary table.
        Console.WriteLine("=== Summary ===");
        Console.WriteLine();
        Console.WriteLine($"{"Rule",-30} {"Findings",>10}");
        Console.WriteLine(new string('-', 42));
        foreach (var (ruleId, count) in rulesWithFindings)
        {
            Console.WriteLine($"{ruleId,-30} {count,>10}");
        }
        Console.WriteLine(new string('-', 42));
        Console.WriteLine($"{"Total",-30} {totalFindings,>10}");
        Console.WriteLine();
        Console.WriteLine($"Audit completed in {elapsed.TotalSeconds:F2}s");
    }
}

/// <summary>
/// A single rendered violation, carrying enough context for the renderer
/// to print the path:line line, explanation, and suggested direction.
/// </summary>
internal sealed record ViolationRecord(
    string Path,
    int Line,
    string Message,
    string Explanation,
    string Direction);

using System.Diagnostics;
using VisualRelay.Guards;

namespace VisualRelay.Audit;

/// <summary>
/// VisualRelay.Audit — diagnostic CLI that EXPLAINS hermeticity findings
/// (file:line, snippet, why it matters, suggested direction) instead of
/// failing a build. It is the complementary occasional-use lens; the
/// guard-as-tests (matchers in VisualRelay.Guards) are the enforcement layer.
///
/// Usage: dotnet run -- [rule-id ...]  (no args = all four rules)
/// Exit 0 when the audit ran (it is informational, never a gate).
/// Exit 2 on unknown subcommand.
/// </summary>
public static class Program
{
    private delegate IReadOnlyList<(string Path, int Line, string Snippet, string Reason)> MatcherFn(
        IEnumerable<(string Path, string Source)> files);

    public static int Main(string[] args)
    {
        var requestedRules = args.Length > 0
            ? new HashSet<string>(args, StringComparer.OrdinalIgnoreCase)
            : null; // null = all rules

        // Validate rule IDs.
        if (requestedRules is not null)
        {
            foreach (var r in requestedRules)
            {
                if (!RuleRegistry.ContainsKey(r))
                {
                    Console.Error.WriteLine($"audit: unknown rule-id '{r}'. Valid rule-ids: {string.Join(", ", RuleRegistry.Keys.Order())}");
                    return 2;
                }
            }
        }

        var repoRoot = GuardRepoRoot.Resolve();
        if (repoRoot is null)
        {
            Console.Error.WriteLine("audit: could not find repo root (no visual-relay file walking up).");
            return 1;
        }

        // Collect all .cs files from src/, tests/, tools/, skipping bin/obj.
        var files = new List<(string Path, string Source)>();
        foreach (var dir in new[] { "src", "tests", "tools" })
        {
            var fullDir = Path.Combine(repoRoot, dir);
            if (!Directory.Exists(fullDir))
                continue;

            foreach (var file in Directory.EnumerateFiles(fullDir, "*.cs", SearchOption.AllDirectories))
            {
                if (IsBuildArtifact(file))
                    continue;

                var relativePath = Path.GetRelativePath(repoRoot, file);
                var source = File.ReadAllText(file);
                files.Add((relativePath, source));
            }
        }

        var stopwatch = Stopwatch.StartNew();

        var findingsByRule = new Dictionary<string, IReadOnlyList<ViolationRecord>>(StringComparer.OrdinalIgnoreCase);

        var rulesToRun = requestedRules is not null
            ? requestedRules
            : new HashSet<string>(RuleRegistry.Keys, StringComparer.OrdinalIgnoreCase);

        foreach (var ruleId in rulesToRun.Order())
        {
            var findings = new List<ViolationRecord>();

            if (ruleId == "real-waits")
            {
                // real-waits: violations from RealSleepGuard + suppression inventory.
                var violations = RealWaitsGuard.FindViolations(files);
                foreach (var v in violations)
                {
                    findings.Add(new ViolationRecord(
                        v.Path, v.Line, ExtractMessage(v.Reason),
                        "A real wall-clock wait was found in source code. This makes tests slow and non-deterministic.",
                        "Replace with a virtual-clock seam (TimeProvider) or use Task.Yield() for yielding."));
                }

                var suppressions = RealWaitsGuard.FindSuppressions(files);
                foreach (var s in suppressions)
                {
                    findings.Add(new ViolationRecord(
                        s.Path, s.Line, s.Reason,
                        "An existing suppression marker; review whether it is still needed.",
                        "If the underlying wait has been fixed, remove the suppression marker to keep the exemption list clean."));
                }
            }
            else
            {
                var violations = RuleRegistry[ruleId](files);
                foreach (var v in violations)
                {
                    var (explanation, direction) = DefaultExplanationAndDirection(ruleId);
                    findings.Add(new ViolationRecord(
                        v.Path, v.Line, ExtractMessage(v.Reason), explanation, direction));
                }
            }

            findingsByRule[ruleId] = findings;
        }

        stopwatch.Stop();

        AuditRenderer.Render(findingsByRule, stopwatch.Elapsed);

        return 0;
    }

    /// <summary>
    /// Strips the rule-id prefix from a reason string (e.g. "retry-delay-loop: ...")
    /// to produce a cleaner message for display.
    /// </summary>
    private static string ExtractMessage(string reason)
    {
        var colonIdx = reason.IndexOf(':');
        return colonIdx >= 0 ? reason[(colonIdx + 1)..].Trim() : reason;
    }

    private static (string Explanation, string Direction) DefaultExplanationAndDirection(string ruleId) => ruleId switch
    {
        "retry-delay-loops" => (
            "A retry loop with a delay is retrying operations that may deterministically fail (e.g. 'not a git repository'). This burns wall-clock time on failures that can never succeed.",
            "Replace the retry loop with a single attempt. If retry is truly needed, classify failures and only retry transient ones."),
        "di-bypass" => (
            "An injection seam (optional parameter) defaults to a real collaborator, and a call site omits the argument. The real collaborator is silently used instead of the injected one.",
            "Pass the injected dependency explicitly at the call site, or remove the real-collaborator default from the optional parameter."),
        "test-side-effects" => (
            "A test source references a real side-effect construct — spawning real processes, mutating the global environment, or using real GitInvoker. This makes tests unhermetic and slow.",
            "Replace with the corresponding hermetic double (NullGitInvoker/GitSim, ScriptedTestRunner, DictionaryEnvironmentAccessor)."),
        _ => ("See details above.", "Consider the suggested double or approach for this pattern."),
    };

    private static bool IsBuildArtifact(string path)
    {
        var segments = path.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        return segments.Any(s => s is "bin" or "obj");
    }

    /// <summary>
    /// Maps rule IDs to matcher functions. Each matcher takes a collection of
    /// (path, source) pairs and returns violations.
    /// </summary>
    private static readonly IReadOnlyDictionary<string, MatcherFn> RuleRegistry =
        new Dictionary<string, MatcherFn>(StringComparer.OrdinalIgnoreCase)
        {
            ["retry-delay-loops"] = files =>
                RetryDelayLoopsGuard.FindViolations(files)
                    .Select(v => (v.Path, v.Line, v.Snippet, v.Reason))
                    .ToList(),

            ["di-bypass"] = files =>
                DiBypassGuard.FindViolations(files)
                    .Select(v => (v.Path, v.Line, v.Snippet, v.Reason))
                    .ToList(),

            ["real-waits"] = files =>
                // real-waits handled specially in Main to include suppressions
                [],

            ["test-side-effects"] = files =>
                TestSideEffectsGuard.FindViolations(files)
                    .Select(v => (v.Path, v.Line, v.Snippet, v.Reason))
                    .ToList(),
        };
}

