using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags method parameters defaulting to a real collaborator
/// (<c>?? new GitInvoker()</c>, <c>?? TimeProvider.System</c>) on an optional
/// param, plus every call site of that method which omits the argument while
/// the enclosing class holds <c>RelayDriverDependencies</c>. This is the
/// <c>EarlyImplementationDetector</c> bug shape: an injection seam silently
/// bypassed because the real collaborator is hard-coded as the default.
///
/// The matcher does a cross-file two-pass walk:
/// <list type="number">
///   <item><b>Pass 1</b> — scan ALL files for methods with optional params
///         (= null default) whose body does <c>param ?? new GitInvoker()</c>
///         or <c>param ?? TimeProvider.System</c>. Record the containing-type
///         name, method name, parameter index, and default kind.</item>
///   <item><b>Pass 2</b> — scan ALL files for invocation expressions matching
///         recorded method names; when the bypassed param-index argument is
///         omitted, check if the enclosing <c>ClassDeclarationSyntax</c> contains
///         a field/property typed <c>RelayDriverDependencies</c>. If so, report
///         the call site as a bypass.</item>
/// </list>
///
/// Self-exempts its own fixture files. No I/O — callers supply the (path, source)
/// pairs.
/// </summary>
public static class DiBypassGuard
{
    /// <summary>Describes a single DI-bypass violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["DiBypassGuard.cs", "DiBypassGuardTests.cs"];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>Internal record for a bypass-default method discovered in Pass 1.</summary>
    private sealed record BypassMethod(
        string ContainingTypeName,
        string MethodName,
        int ParamIndex,
        string ParamName,
        string DefaultKind); // e.g. "new GitInvoker()", "TimeProvider.System"

    /// <summary>
    /// Returns every DI-bypass violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line. Self-exempt files yield nothing.
    /// Does a cross-file two-pass analysis.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var fileList = files.Where(f => !SelfExemptFileNames.Contains(Path.GetFileName(f.Path))).ToList();
        if (fileList.Count == 0)
            return [];

        // Pass 1: find all bypass methods across ALL files.
        var bypassMethods = new List<BypassMethod>();
        foreach (var (path, source) in fileList)
        {
            var tree = CSharpSyntaxTree.ParseText(source, ParseOptions);
            CollectBypassMethods(tree.GetRoot(), bypassMethods);
        }

        if (bypassMethods.Count == 0)
            return [];

        // Pass 2: find call sites across ALL files.
        var violations = new List<Violation>();
        foreach (var (path, source) in fileList)
        {
            var tree = CSharpSyntaxTree.ParseText(source, ParseOptions);
            FindCallSites(path, tree, bypassMethods, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>
    /// Returns every DI-bypass violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Self-exempt files yield nothing.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var treeList = trees.Where(t => !SelfExemptFileNames.Contains(Path.GetFileName(t.Path))).ToList();
        if (treeList.Count == 0)
            return [];

        // Pass 1: find all bypass methods.
        var bypassMethods = new List<BypassMethod>();
        foreach (var (_, tree) in treeList)
        {
            CollectBypassMethods(tree.GetRoot(), bypassMethods);
        }

        if (bypassMethods.Count == 0)
            return [];

        // Pass 2: find call sites.
        var violations = new List<Violation>();
        foreach (var (path, tree) in treeList)
        {
            FindCallSites(path, tree, bypassMethods, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    // ── Pass 1: collect methods with bypass-default optional params ──

    private static void CollectBypassMethods(SyntaxNode root, List<BypassMethod> sink)
    {
        foreach (var method in root.DescendantNodes().OfType<MethodDeclarationSyntax>())
        {
            var containingType = method.Parent is ClassDeclarationSyntax cls
                ? cls.Identifier.Text
                : string.Empty;

            var parameters = method.ParameterList.Parameters;
            for (int i = 0; i < parameters.Count; i++)
            {
                var param = parameters[i];
                if (param.Default is null || param.Default.Value is not LiteralExpressionSyntax lit)
                    continue;
                if (lit.Token.Value is not null) // ignore non-null defaults
                    continue;

                // Look in the method body for: paramId ?? <real-collaborator>
                var paramId = param.Identifier.Text;
                var body = (SyntaxNode?)method.Body ?? method.ExpressionBody;
                if (body is null)
                    continue;

                var defaultKind = FindBypassDefault(body, paramId);
                if (defaultKind is null)
                    continue;

                sink.Add(new BypassMethod(containingType, method.Identifier.Text, i, paramId, defaultKind));
            }
        }
    }

    // ── Pass 2: find call sites omitting bypassed args ──

    private static void FindCallSites(string path, SyntaxTree tree, List<BypassMethod> bypassMethods, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();

        foreach (var call in root.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            string? methodName;
            string? receiverTypeName;

            if (call.Expression is MemberAccessExpressionSyntax ma)
            {
                methodName = ma.Name.Identifier.Text;
                receiverTypeName = RightmostIdentifier(ma.Expression);
            }
            else if (call.Expression is IdentifierNameSyntax simple)
            {
                methodName = simple.Identifier.Text;
                receiverTypeName = null; // simple name — match on method name only
            }
            else
            {
                continue;
            }

            // Find matching bypass methods.
            var matching = bypassMethods
                .Where(bm => bm.MethodName == methodName)
                .Where(bm => receiverTypeName is null
                             || string.IsNullOrEmpty(bm.ContainingTypeName)
                             || bm.ContainingTypeName == receiverTypeName)
                .ToList();

            if (matching.Count == 0)
                continue;

            var argCount = call.ArgumentList.Arguments.Count;

            foreach (var bm in matching)
            {
                if (argCount <= bm.ParamIndex)
                {
                    if (EnclosingClassHoldsDependencies(call))
                    {
                        var line = LineOf(text, call.SpanStart);
                        sink.Add(new Violation(path, line, SnippetOf(text, line),
                            $"di-bypass: call to {bm.ContainingTypeName}.{bm.MethodName} omits param " +
                            $"'{bm.ParamName}' (#{bm.ParamIndex + 1}) which defaults to {bm.DefaultKind} " +
                            $"— enclosing class holds RelayDriverDependencies"));
                    }
                }
            }
        }
    }

    // ── Helpers ──

    private static string? FindBypassDefault(SyntaxNode body, string paramId)
    {
        foreach (var coalesce in body.DescendantNodes().OfType<BinaryExpressionSyntax>())
        {
            if (!coalesce.IsKind(SyntaxKind.CoalesceExpression))
                continue;

            if (coalesce.Left is IdentifierNameSyntax id && id.Identifier.Text == paramId)
            {
                return DescribeDefault(coalesce.Right);
            }
        }

        return null;
    }

    private static string? DescribeDefault(ExpressionSyntax expr)
    {
        if (expr is ObjectCreationExpressionSyntax oce
            && RightmostTypeName(oce.Type) is { } typeName
            && (typeName.StartsWith("Git", StringComparison.Ordinal) || typeName == "GitInvoker"))
        {
            return $"new {typeName}()";
        }

        if (expr is MemberAccessExpressionSyntax ma
            && ma.Name.Identifier.Text == "System"
            && RightmostIdentifier(ma.Expression) == "TimeProvider")
        {
            return "TimeProvider.System";
        }

        return null;
    }

    private static bool EnclosingClassHoldsDependencies(SyntaxNode node)
    {
        var cls = node.FirstAncestorOrSelf<ClassDeclarationSyntax>();
        if (cls is null)
            return false;

        foreach (var field in cls.Members.OfType<FieldDeclarationSyntax>())
        {
            var typeName = RightmostTypeName(field.Declaration.Type);
            if (typeName == "RelayDriverDependencies")
                return true;
        }

        foreach (var prop in cls.Members.OfType<PropertyDeclarationSyntax>())
        {
            var typeName = RightmostTypeName(prop.Type);
            if (typeName == "RelayDriverDependencies")
                return true;
        }

        return false;
    }

    private static string RightmostIdentifier(ExpressionSyntax expr) => expr switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        MemberAccessExpressionSyntax ma => ma.Name.Identifier.Text,
        _ => string.Empty,
    };

    private static string RightmostTypeName(TypeSyntax type) => type switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        QualifiedNameSyntax qn => qn.Right.Identifier.Text,
        _ => type.ToString(),
    };

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

