using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Flags <c>for</c>/<c>while</c> loops containing BOTH a delay call
/// (<c>Task.Delay</c>/<c>Thread.Sleep</c>) AND an invocation whose receiver or
/// args involve <c>IGitInvoker</c>, <c>RunAsync</c>, or process types — the
/// <c>RunGitAsync</c> bug shape: retrying deterministic failures (e.g. exit-128
/// <c>fatal: not a git repository</c>).
///
/// Reports loop kind, attempt/backoff constants, and whether a failure-classifier
/// identifier is present. Self-exempts its own fixture files. No I/O.
/// </summary>
public static class RetryDelayLoopsGuard
{
    /// <summary>Describes a single retry-delay-loop violation (1-based line).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["RetryDelayLoopsGuard.cs", "RetryDelayLoopsGuardTests.cs"];

    private static readonly HashSet<string> ClassifierHints = new(StringComparer.OrdinalIgnoreCase)
    {
        "isSuccess", "isSuccessExit", "shouldRetry", "canRetry", "isTransient",
        "isRetryable", "isRecoverable",
    };

    private static readonly HashSet<string> DelayMethods =
        new(StringComparer.Ordinal) { "Delay", "Sleep" };

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    // ── Public API ──

    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var list = new List<Violation>();
        foreach (var (p, s) in files)
            if (!SelfExemptFileNames.Contains(Path.GetFileName(p)))
                Scan(p, CSharpSyntaxTree.ParseText(s, ParseOptions).GetRoot(), s, list);
        return Sorted(list);
    }

    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var list = new List<Violation>();
        foreach (var (p, t) in trees)
            if (!SelfExemptFileNames.Contains(Path.GetFileName(p)))
                Scan(p, t.GetRoot(), t.GetText(), list);
        return Sorted(list);
    }

    // ── Core scan ──

    private static void Scan(string path, SyntaxNode root, SourceText text, List<Violation> sink)
    {
        foreach (var loop in root.DescendantNodes())
        {
            StatementSyntax? body;
            string kind;
            if (loop is ForStatementSyntax f)
            { body = f.Statement; kind = "for"; }
            else if (loop is WhileStatementSyntax w)
            { body = w.Statement; kind = "while"; }
            else
                continue;

            if (body is null) continue;

            var invocations = body.DescendantNodes().OfType<InvocationExpressionSyntax>().ToList();
            if (invocations.Count == 0) continue;

            if (!invocations.Any(IsDelayCall) || !invocations.Any(IsSensitive))
                continue;

            var constants = ExtractConstants(loop, invocations);
            var hasClassifier = invocations.Any(HasClassifierIdentifier)
                                || loop.DescendantNodes().OfType<IdentifierNameSyntax>().Any(id =>
                                    ClassifierHints.Contains(id.Identifier.Text)
                                    || id.Identifier.Text.Contains("Classifier", StringComparison.Ordinal)
                                    || id.Identifier.Text.Contains("classifier", StringComparison.Ordinal));

            var reason = $"retry-delay-loop: {kind}-loop retries a potentially deterministic failure with delay" +
                         (constants.Count > 0 ? $" (constants: {string.Join(", ", constants)})" : "") +
                         (hasClassifier ? " — failure classifier present" : " — no failure classifier found");

            var line = text.Lines.GetLinePosition(loop.GetLocation().SourceSpan.Start).Line + 1;
            if (IsAllowMarked(text, line)) continue;

            sink.Add(new Violation(path, line, Snippet(text, line), reason));
        }
    }

    // ── Detection predicates ──

    private static bool IsDelayCall(InvocationExpressionSyntax inv)
    {
        if (inv.Expression is not MemberAccessExpressionSyntax ma) return false;
        if (!DelayMethods.Contains(ma.Name.Identifier.Text)) return false;
        return RightmostId(ma.Expression) is "Task" or "Thread";
    }

    private static bool IsSensitive(InvocationExpressionSyntax inv)
    {
        if (inv.Expression is not MemberAccessExpressionSyntax ma) return false;
        var method = ma.Name.Identifier.Text;
        var recv = RightmostId(ma.Expression);

        // GitInvoker receiver, Process receiver, RunAsync, Process.Start
        if (recv.Contains("GitInvoker", StringComparison.OrdinalIgnoreCase)
            || recv.Contains("gitInvoker", StringComparison.OrdinalIgnoreCase)
            || recv == "gi" || recv == "Process" || method == "RunAsync"
            || (method == "Start" && recv == "Process"))
            return true;

        // Argument is a ProcessStartInfo creation
        return inv.ArgumentList.Arguments.Any(a =>
            a.Expression is ObjectCreationExpressionSyntax o
            && RightmostTypeName(o.Type) == "ProcessStartInfo");
    }

    private static bool HasClassifierIdentifier(InvocationExpressionSyntax inv) =>
        inv.Ancestors().OfType<StatementSyntax>().Any(stmt =>
            stmt.DescendantNodes().OfType<IdentifierNameSyntax>().Any(id =>
                ClassifierHints.Contains(id.Identifier.Text)));

    // ── Constant extraction ──

    private static List<string> ExtractConstants(SyntaxNode loop, List<InvocationExpressionSyntax> invocations)
    {
        var c = new List<string>();
        foreach (var lit in loop.DescendantNodes().OfType<LiteralExpressionSyntax>())
        {
            if (lit.Token.Value is int i && i is > 0 and <= 100
                && lit.Parent is (BinaryExpressionSyntax or VariableDeclaratorSyntax))
                c.Add($"maxAttempts={i}");
        }

        foreach (var inv in invocations)
        {
            if (!IsDelayCall(inv)) continue;
            foreach (var arg in inv.ArgumentList.Arguments)
            {
                if (arg.Expression is InvocationExpressionSyntax iExpr
                    && iExpr.Expression is MemberAccessExpressionSyntax m2
                    && m2.Expression is MemberAccessExpressionSyntax ts
                    && ts.Name.Identifier.Text is "FromMilliseconds" or "FromSeconds"
                    && RightmostId(ts.Expression) == "TimeSpan"
                    && iExpr.ArgumentList.Arguments.Count >= 1
                    && iExpr.ArgumentList.Arguments[0].Expression is LiteralExpressionSyntax lit
                    && lit.Token.Value is int val)
                    c.Add($"delay={val}{(ts.Name.Identifier.Text == "FromMilliseconds" ? "ms" : "s")}");
                else if (arg.Expression is LiteralExpressionSyntax l && l.Token.Value is int ms)
                    c.Add($"delay={ms}ms");
            }
        }

        return c.Distinct().Take(6).ToList();
    }

    // ── Utility ──

    private static bool IsAllowMarked(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString();
        return s.Contains("// vr-allow-retry-delay-loop:", StringComparison.Ordinal)
               && !s.EndsWith("vr-allow-retry-delay-loop:", StringComparison.Ordinal);
    }

    private static string RightmostId(ExpressionSyntax e) => e switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        MemberAccessExpressionSyntax ma => ma.Name.Identifier.Text,
        _ => "",
    };

    private static string RightmostTypeName(TypeSyntax t) => t switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        QualifiedNameSyntax qn => qn.Right.Identifier.Text,
        _ => t.ToString(),
    };

    private static string Snippet(SourceText t, int line)
    {
        var s = t.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }

    private static IReadOnlyList<Violation> Sorted(List<Violation> list)
    {
        list.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return list;
    }
}

